-}
+export function cartTotal(items, coupon) {
+  let total = 0;
+  for (let i = 0; i < items.length; i++) {
+    const price = parseFloat(items[i].price);
+    total = total + price * items[i].qty;
+  }
+  if (coupon == "SAVE10") {
+    total = total * 0.9;
+  }
+  return Math.round(total * 100) / 100;
+}
+
+export function renderCart(el, items, coupon) {
+  const total = cartTotal(items, coupon);
+  el.innerHTML = "<h3>Total: $" + total + "</h3><p>" + coupon + "</p>";
+}
+
+export function cartSubtotal(items) {
+  let total = 0;
+  for (let i = 0; i < items.length; i++) {
+    const price = parseFloat(items[i].price);
+    total = total + price * items[i].qty;
+  }
+  return Math.round(total * 100) / 100;
+}
+
+export async function saveCart(api, items) {
+  try {
+    await api.post("/cart", { items });
+  } catch (e) {}
+}
